const webhookItem = $('Webhook').first().json;
const data = webhookItem.body.data;

if (data.key?.fromMe === true) {
  return [];
}

const msgTimestamp = data.messageTimestamp;
const nowSeconds = Math.floor(Date.now() / 1000);
const MAX_AGE_SECONDS = 600;
if (msgTimestamp && (nowSeconds - msgTimestamp) > MAX_AGE_SECONDS) {
  return [];
}

const texto = data.message.conversation;
const numeroRemetente = data.key.remoteJid;
const nomeContato = data.pushName || 'Desconhecido';

// --- Carrega usuários da planilha e identifica o nível de quem enviou ---
const usuarios = $input.all().map(i => i.json);
const numeroRemetenteLimpo = numeroRemetente.replace('@s.whatsapp.net', '');
const usuarioAtual = usuarios.find(u => String(u.Numero) === numeroRemetenteLimpo);
const nivelAtual = usuarioAtual ? usuarioAtual.Nivel : 'Desconhecido';
// --- BLOQUEIO: só usuários cadastrados podem usar o bot ---
if (nivelAtual === 'Desconhecido') {
  return [{
    json: {
      tipo: 'nao_cadastrado',
      numero: numeroRemetente,
      nomeContato,
      textoResposta: '❌ Você ainda não está cadastrado no LabFlow. Peça a um administrador para te cadastrar.'
    }
  }];
}
// Sinaliza se o nome do WhatsApp de quem mandou mudou (ou nunca foi
// preenchido) em relação ao que já está salvo na USUARIOS — só pra quem
// já é cadastrado (nunca cria cadastro novo por essa via).
const sincronizarNome = !!(usuarioAtual && usuarioAtual.Nome !== nomeContato);

// Toda resposta passa por aqui, pra sempre levar junto os dados de
// sincronização de nome sem precisar repetir em cada bloco abaixo.
function output(json) {
  return [{
    json: {
      ...json,
      _sincronizarNome: sincronizarNome,
      _numeroRemetenteLimpo: numeroRemetenteLimpo,
      _nomeContatoAtual: nomeContato
    }
  }];
}
// Calcula as N linhas de análise (CT, BL, WORT) para um tanque, a partir
// da data em que o frasco (Normal ou Stress) foi analisado.
function calcularAnalises(dataAnaliseStr, idColeta, tanque, tipoFrasco, tipoTanque, navio) {
  const [dia, mes, ano] = dataAnaliseStr.split('/').map(Number);
  const dataBase = new Date(ano, mes - 1, dia);

  const formatarData = (d) =>
    `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;

  const somarHoras = (dataBase, horas) => {
    const d = new Date(dataBase);
    d.setHours(d.getHours() + horas);
    return d;
  };

  // Config: { pre: horas ou null, final: horas }
  const PRAZOS = {
    CT:   { pre: null, final: 48 },
    BL:   { pre: 72,   final: 120 },
    WORT: { pre: 120,  final: 240 }
  };

  // Cada linha: { subAnalise, metodo }
  const LINHAS = [
    { subAnalise: 'CT',   metodo: 'Profundidade' },
    { subAnalise: 'BL',   metodo: 'Profundidade' },
    { subAnalise: 'WORT', metodo: 'Profundidade' },
    { subAnalise: 'WORT', metodo: 'Superficie' }
  ];

  return LINHAS.map(({ subAnalise, metodo }, idx) => {
    const prazo = PRAZOS[subAnalise];
    const dataPreLeitura = prazo.pre !== null
      ? formatarData(somarHoras(dataBase, prazo.pre))
      : '';
    const dataLeituraFinal = formatarData(somarHoras(dataBase, prazo.final));
    const status = prazo.pre !== null
      ? 'Aguardando Pré-Leitura'
      : 'Aguardando Leitura Final';

    return {
      idAnalise: `AN-${idColeta}-${tipoFrasco}-${subAnalise}-${metodo}`.slice(0, 60),
      idColeta,
      tanque,
      tipoTanque,
      navio: navio || '',
      tipoFrasco,
      subAnalise,
      metodo,
      dataAnalise: dataAnaliseStr,
      dataPreLeitura,
      dataLeituraFinal,
      status,
      responsavel: nomeContato
    };
  });
}
// Calcula as 3 datas de drop (D5, D10, D15) a partir da data de coleta
function calcularDrops(dataColetaStr, idColeta, tanque, tipoTanque, navio) {
  const [dia, mes, ano] = dataColetaStr.split('/').map(Number);
  const dataBase = new Date(ano, mes - 1, dia);
  const dias = [5, 10, 15];
  return dias.map(offset => {
    const dataDrop = new Date(dataBase);
    dataDrop.setDate(dataDrop.getDate() + offset);
    const dd = String(dataDrop.getDate()).padStart(2, '0');
    const mm = String(dataDrop.getMonth() + 1).padStart(2, '0');
    const yyyy = dataDrop.getFullYear();
    return {
      idDrop: `DR-${idColeta}-${offset}`,
      idColeta: idColeta,
      tipoTanque: tipoTanque,
      tanque: tanque,
      navio: navio || '',
      diaDrop: `D${offset}`,
      dataPrevista: `${dd}/${mm}/${yyyy}`,
      status: 'Pendente',
      responsavel: nomeContato
    };
  });
}
function calcularArquivo(dataColetaStr, idColeta, tanque, navio) {
  const [dia, mes, ano] = dataColetaStr.split('/').map(Number);
  const dataColeta = new Date(ano, mes - 1, dia);
  const dataDescarte = new Date(dataColeta);
  dataDescarte.setDate(dataDescarte.getDate() + 365);

  const formatarData = (d) =>
    `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;

  return {
    id: `AR-${idColeta}`,
    idColeta,
    tanque,
    navio: navio || '',
    dataColeta: dataColetaStr,
    dataDescarte: formatarData(dataDescarte),
    status: 'Arquivado',
    responsavel: nomeContato
  };
}

// --- GERENCIAR USUARIO ---
const regexGerenciarUsuario = /(adicionar|trocar|mudar)\s+cargo\s+(?:de\s+)?(\w+)\s+para\s+o?\s*n[uú]mero\s+(\d+)(?:\s+nome\s+(.+))?/i;
const matchGerenciar = texto.match(regexGerenciarUsuario);

if (matchGerenciar) {
  const nivelNovo = matchGerenciar[2];
  const numeroAlvo = matchGerenciar[3];
  const nomeInformado = matchGerenciar[4] ? matchGerenciar[4].trim() : null;

  if (nivelAtual !== 'Admin') {
    return output({
      tipo: 'gerenciar_usuario',
      autorizado: false,
      numero: numeroRemetente,
      nomeContato,
      textoResposta: '❌ Só administradores podem alterar cargos de usuários.'
    });
  }

  const niveisValidos = ['Admin', 'Operador', 'Consultor'];
  if (!niveisValidos.includes(nivelNovo)) {
    return output({
      tipo: 'gerenciar_usuario',
      autorizado: false,
      numero: numeroRemetente,
      nomeContato,
      textoResposta: `❌ Cargo inválido. Use: ${niveisValidos.join(' ou ')}.`
    });
  }

  const usuarioAlvoExistente = usuarios.find(u => String(u.Numero) === numeroAlvo);
  let nomeAlvo;
  if (nomeInformado) {
    nomeAlvo = nomeInformado;
  } else if (numeroAlvo === numeroRemetenteLimpo) {
    nomeAlvo = nomeContato;
  } else {
    nomeAlvo = usuarioAlvoExistente ? usuarioAlvoExistente.Nome : '';
  }

  return output({
    tipo: 'gerenciar_usuario',
    autorizado: true,
    numero: numeroRemetente,
    nomeContato,
    NumeroAlvo: numeroAlvo,
    NivelNovo: nivelNovo,
    NomeAlvo: nomeAlvo,
    textoResposta: nomeAlvo
      ? `✅ Cargo atualizado: numero ${numeroAlvo} (${nomeAlvo}) agora é ${nivelNovo}.`
      : `✅ Cargo atualizado: numero ${numeroAlvo} agora é ${nivelNovo}.`
  });
}
// Bloqueia comandos de registro para quem só tem acesso de consulta.
function bloqueadoConsultor() {
  if (nivelAtual === 'Consultor') {
    return output({
      tipo: 'erro_coleta',
      numero: numeroRemetente,
      nomeContato,
      textoResposta: '❌ Consultores têm acesso somente de consulta. Peça a um administrador para registrar isso.'
    });
  }
  return null;
}
// --- COLETA TANQUE TERRA ---
if (/registrar\s+coleta\s+tanques?\s+terra/i.test(texto)) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  const matchTanques = texto.match(/tanques?\s+terra\s+([a-z0-9,\s]+?)\s+data\s+(\d{2}\/\d{2}\/\d{4})/i);

  if (!matchTanques) {
    return output({
      tipo: 'erro_coleta',
      numero: numeroRemetente,
      nomeContato,
      textoResposta:
        '❌ Não foi possível registrar a coleta de terra.\n\n' +
        'Formato esperado:\n"registrar coleta tanque(s) terra <número(s)> data <dd/mm/aaaa>"'
    });
  }

  const tanques = matchTanques[1].split(',').map(t => t.trim()).filter(Boolean);
  const dataColeta = matchTanques[2];

  if (tanques.length === 0) {
    return output({
      tipo: 'erro_coleta',
      numero: numeroRemetente,
      nomeContato,
      textoResposta:
        '❌ Não foi possível registrar a coleta de terra — nenhum tanque reconhecido.\n\n' +
        'Formato esperado:\n"registrar coleta tanque(s) terra <número(s)> data <dd/mm/aaaa>"'
    });
  }

  if (tanques.length > 8) {
    return output({
      tipo: 'erro_coleta',
      numero: numeroRemetente,
      nomeContato,
      textoResposta:
        `❌ Só é possível registrar até 8 tanques por mensagem (você enviou ${tanques.length}). ` +
        'Divida em mais de uma mensagem.'
    });
  }

  const itensColeta = [];
  let drops = [];
  let bagsArquivo = [];

  tanques.forEach((tanque, idx) => {
    const idColeta = `CT-${Date.now()}-${idx}`;

    itensColeta.push({ idColeta, tanque, dataColeta, responsavel: nomeContato });
    drops = drops.concat(calcularDrops(dataColeta, idColeta, tanque, 'Terra', null));
    bagsArquivo.push(calcularArquivo(dataColeta, idColeta, tanque, null));
  });

  return output({
    tipo: 'coleta_terra',
    dataColeta,
    tanques,
    itensColeta,
    drops,
    bagsArquivo,
    numero: numeroRemetente,
    nomeContato,
    textoResposta:
      `✅ Coleta de terra registrada.\n\nTanques: ${tanques.join(', ')}\n` +
      `Data: ${dataColeta}\n` +
      `Total: ${tanques.length} tanque${tanques.length === 1 ? '' : 's'}`
  });
}

// --- COLETA TANQUE NAVIO ---
if (/coleta navio/i.test(texto)) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  const matchNavio = texto.match(/coleta\s+navio\s+(.+?)\s+tanques\s+([a-z0-9,\s]+?)\s+data\s+(\d{2}\/\d{2}\/\d{4})/i);

  if (!matchNavio) {
    return output({
      tipo: 'erro_coleta',
      numero: numeroRemetente,
      nomeContato,
      textoResposta:
        '❌ Não foi possível registrar a coleta de navio.\n\n' +
        'Formato esperado:\n"Coleta navio <nome> tanques <lista separada por vírgula> data <dd/mm/aaaa>"'
    });
  }

  const navio = matchNavio[1].trim();
  const tanques = matchNavio[2].split(',').map(t => t.trim().toUpperCase()).filter(Boolean);
  const dataColeta = matchNavio[3];

  if (!navio || tanques.length === 0) {
    return output({
      tipo: 'erro_coleta',
      numero: numeroRemetente,
      nomeContato,
      textoResposta:
        '❌ Não foi possível registrar a coleta de navio — nome do navio ou lista de tanques veio vazia.\n\n' +
        'Formato esperado:\n"Coleta navio <nome> tanques <lista separada por vírgula> data <dd/mm/aaaa>"'
    });
  }

  const itensColeta = [];
  let drops = [];
  let arquivosNavio = [];

  tanques.forEach((tanque, idx) => {
    const idColeta = `CN-${Date.now()}-${idx}`;

    itensColeta.push({
      idColeta,
      navio,
      tanque,
      dataColeta,
      responsavel: nomeContato
    });

    drops = drops.concat(
      calcularDrops(dataColeta, idColeta, tanque, 'Navio', navio)
    );

    arquivosNavio.push(
      calcularArquivo(dataColeta, idColeta, tanque, navio)
    );
  });

  return output({
    tipo: 'coleta_navio',
    navio,
    dataColeta,
    tanques,
    itensColeta,
    drops,
    arquivosNavio,
    numero: numeroRemetente,
    nomeContato,
    textoResposta:
      `✅ Coleta registrada.\n\nNavio: ${navio}\n` +
      `Tanques: ${tanques.join(', ')}\n` +
      `Data: ${dataColeta}\n` +
      `Total: ${tanques.length} tanque${tanques.length === 1 ? '' : 's'}`
  });
}

// --- ANALISE DE TANQUE (NORMAL / STRESS) — terra e navio, lista de tanques ---
const regexAnaliseTanque = /an[aá]lise\s+(?:dos?\s+)?(normal|stress)\s+(?:dos?\s+)?tanques?\s+(?:terra\s+)?([a-z0-9,\s]+?)(?:\s+navio\s+(.+?))?\s*,?\s*data\s+(\d{2}\/\d{2}\/\d{4})/i;
const matchAnaliseTanque = texto.match(regexAnaliseTanque);

if (matchAnaliseTanque) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  const tipoFrascoBruto = matchAnaliseTanque[1].toLowerCase();
  const tipoFrasco = tipoFrascoBruto === 'stress' ? 'Stress' : 'Normal';
  const tanques = matchAnaliseTanque[2].split(',').map(t => t.trim().toUpperCase()).filter(Boolean);
  const navio = matchAnaliseTanque[3] ? matchAnaliseTanque[3].trim().toUpperCase() : null;
  const tipoTanque = navio ? 'Navio' : 'Terra';
  const dataAnalise = matchAnaliseTanque[4];

  if (tanques.length === 0) {
    return output({
      tipo: 'erro_coleta',
      numero: numeroRemetente,
      nomeContato,
      textoResposta:
        '❌ Não foi possível registrar a análise — nenhum tanque reconhecido.\n\n' +
        'Formato esperado:\n"Analise do normal/stress do tanque(s) <número(s)>[ navio <nome>], data <dd/mm/aaaa>"'
    });
  }

  const limite = navio ? 16 : 8;
  if (tanques.length > limite) {
    return output({
      tipo: 'erro_coleta',
      numero: numeroRemetente,
      nomeContato,
      textoResposta:
        `❌ Só é possível registrar até ${limite} tanques por mensagem${navio ? ' de navio' : ''} (você enviou ${tanques.length}). ` +
        'Divida em mais de uma mensagem.'
    });
  }

  const idColetaBase = `AN-${Date.now()}`;
  let analises = [];
  tanques.forEach((tanque, idx) => {
    const idColeta = `${idColetaBase}-${idx}`;
    analises = analises.concat(calcularAnalises(dataAnalise, idColeta, tanque, tipoFrasco, tipoTanque, navio));
  });
  const analiseCT = analises.find(a => a.subAnalise === 'CT');
  const analiseBL = analises.find(a => a.subAnalise === 'BL');
  const analiseWORT = analises.find(a => a.subAnalise === 'WORT');

  return output({
    tipo: 'registro_analise',
    tipoFrasco,
    tanques,
    tipoTanque,
    navio,
    dataAnalise,
    analises,
    numero: numeroRemetente,
    nomeContato,
    textoResposta:
      `✅ Análise ${tipoFrasco} registrada.\n\n` +
      `Tanques: ${tanques.join(', ')}${navio ? ` (Navio ${navio})` : ''}\n` +
      `Data: ${dataAnalise}\n` +
      `Data final CT: ${analiseCT.dataLeituraFinal}\n` +
      `Data pré-leitura BL: ${analiseBL.dataPreLeitura}\n` +
      `Data final BL: ${analiseBL.dataLeituraFinal}\n` +
      `Data pré-leitura WORT: ${analiseWORT.dataPreLeitura}\n` +
      `Data final WORT: ${analiseWORT.dataLeituraFinal}\n` +
      `Total: ${tanques.length} tanque${tanques.length === 1 ? '' : 's'}\n` +
      `Analises realizadas: CT, BL, WORT (Profundidade e Superfície)`
  });
}

// --- CONSULTA DE DROPS ---
if (/^drops?\s*(previstos)?\s*(para)?\s*hoje\??$/i.test(texto.trim())) {
  return output({
    tipo: 'consulta_drops',
    numero: numeroRemetente,
    nomeContato
  });
}
// --- CONSULTA DE ANALISES (TERRA) ---
if (/^quais\s+analises?\s+(de\s+)?tanques?\s+terra\s+saem\s+hoje\??$/i.test(texto.trim())) {
  return output({
    tipo: 'consulta_analises_terra',
    numero: numeroRemetente,
    nomeContato
  });
}

// --- CONSULTA DE ANALISES (NAVIO) ---
if (/^quais\s+analises?\s+(de\s+)?tanques?\s+navio\s+saem\s+hoje\??$/i.test(texto.trim())) {
  return output({
    tipo: 'consulta_analises_navio',
    numero: numeroRemetente,
    nomeContato
  });
}
// --- CONSULTA DE BAGS (TERRA) ---
if (/^quais\s+bags?\s+(posso\s+)?descartar\s+hoje/i.test(texto.trim())) {
  return output({
    tipo: 'consulta_bags',
    numero: numeroRemetente,
    nomeContato
  });
}

// --- CONSULTA DE POTES (NAVIO) ---
if (/^quais\s+potes?\s+(do\s+)?navio\s+(posso\s+)?descartar\s+hoje/i.test(texto.trim())) {
  return output({
    tipo: 'consulta_potes',
    numero: numeroRemetente,
    nomeContato
  });
}
// --- CONCLUIR DROPS EM LOTE ---
const regexConcluirDrops = /concluir\s+drops?\s+(?:(d5|d10|d15)\s+)?(terra|navio)(?:\s+(.+))?\s*$/i;
const matchConcluirDrops = texto.match(regexConcluirDrops);

if (matchConcluirDrops) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;

  const diaFiltro = matchConcluirDrops[1] ? matchConcluirDrops[1].toUpperCase() : null;
  const tipoTanqueFiltro = matchConcluirDrops[2].toLowerCase() === 'navio' ? 'Navio' : 'Terra';
  const navioFiltro = (tipoTanqueFiltro === 'Navio' && matchConcluirDrops[3])
    ? matchConcluirDrops[3].trim().toUpperCase()
    : null;

  return output({
    tipo: 'concluir_drops',
    diaFiltro,
    tipoTanqueFiltro,
    navioFiltro,
    numero: numeroRemetente,
    nomeContato
  });
}
// --- CONCLUIR LEITURA DE ANALISE (CT/BL/WORT) - TERRA ---
const regexConcluirLeituraTerra = /concluir\s+(?:(pre|final)\s+)?leitura\s+(?:(ct|bl|wort)\s+)?(?:(normal|stress)\s+)?terra\s*$/i;
const matchConcluirLeituraTerra = texto.match(regexConcluirLeituraTerra);

if (matchConcluirLeituraTerra) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;

  const estagioFiltro = matchConcluirLeituraTerra[1] ? matchConcluirLeituraTerra[1].toLowerCase() : null;
  const subAnaliseFiltro = matchConcluirLeituraTerra[2] ? matchConcluirLeituraTerra[2].toUpperCase() : null;
  const frascoFiltro = matchConcluirLeituraTerra[3]
    ? (matchConcluirLeituraTerra[3].toLowerCase() === 'stress' ? 'Stress' : 'Normal')
    : null;

  return output({
    tipo: 'concluir_leitura_terra',
    estagioFiltro,
    subAnaliseFiltro,
    frascoFiltro,
    tipoTanqueFiltro: 'Terra',
    navioFiltro: null,
    numero: numeroRemetente,
    nomeContato
  });
}

// --- CONCLUIR LEITURA DE ANALISE (CT/BL/WORT) - NAVIO ---
const regexConcluirLeituraNavio = /concluir\s+(?:(pre|final)\s+)?leitura\s+(?:(ct|bl|wort)\s+)?(?:(normal|stress)\s+)?navio(?:\s+(.+))?\s*$/i;
const matchConcluirLeituraNavio = texto.match(regexConcluirLeituraNavio);

if (matchConcluirLeituraNavio) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;

  const estagioFiltro = matchConcluirLeituraNavio[1] ? matchConcluirLeituraNavio[1].toLowerCase() : null;
  const subAnaliseFiltro = matchConcluirLeituraNavio[2] ? matchConcluirLeituraNavio[2].toUpperCase() : null;
  const frascoFiltro = matchConcluirLeituraNavio[3]
    ? (matchConcluirLeituraNavio[3].toLowerCase() === 'stress' ? 'Stress' : 'Normal')
    : null;
  const navioFiltro = matchConcluirLeituraNavio[4] ? matchConcluirLeituraNavio[4].trim().toUpperCase() : null;

  return output({
    tipo: 'concluir_leitura_navio',
    estagioFiltro,
    subAnaliseFiltro,
    frascoFiltro,
    tipoTanqueFiltro: 'Navio',
    navioFiltro,
    numero: numeroRemetente,
    nomeContato
  });
}

// --- CONFIRMAR PENDENCIA (resposta "sim" isolada) ---
if (/^sim\s*$/i.test(texto.trim())) {
  return output({
    tipo: 'confirmar_pendencia',
    numero: numeroRemetente,
    nomeContato
  });
}

// --- CANCELAR PENDENCIA (resposta "nao"/"não" isolada) ---
if (/^n[aã]o\s*$/i.test(texto.trim())) {
  return output({
    tipo: 'cancelar_pendencia',
    numero: numeroRemetente,
    nomeContato
  });
}

// --- AMOSTRA (fluxo existente, sem mudança de lógica) ---
const regexAmostra = /amostra\s+(\d+)/i;
const regexAnalise = /analise\s+([a-zA-ZÀ-ú]+)/i;
const regexData = /(\d{2}\/\d{2}\/\d{4})/;

const matchAmostra = texto.match(regexAmostra);
const matchAnalise = texto.match(regexAnalise);
const matchDataAmostra = texto.match(regexData);

return output({
  tipo: 'amostra',
  idRegistro: `AM-${Date.now()}`,
  amostra: matchAmostra ? matchAmostra[1] : null,
  analise: matchAnalise ? matchAnalise[1] : null,
  data: matchDataAmostra ? matchDataAmostra[1] : null,
  mensagem_original: texto,
  numero: numeroRemetente,
  nomeContato: nomeContato
});

